import type { NodeRegistry } from "@spiky-panda/core";
import { createLeakCo2Node, LeakCo2Node } from "./leak-co2.node.js";

/** The type, named under Generated. so that every catalogue says it is generated. */
export const LEAK_CO2_TYPE = "Generated.Habitat:leak-co2";

/** The entry the forge calls: register every type of the plugin on the registry; `doc` turns a card's file name into the path the catalogue hands out. */
export function register(registry: NodeRegistry, doc: (file: string) => string): void {
    const reg = registry as unknown as { register: (type: string, factory: () => unknown, meta: Record<string, unknown>) => void };
    // The ports are the class's own declarations, read off one instance: never retyped here.
    const node = new LeakCo2Node();
    reg.register(LEAK_CO2_TYPE, () => createLeakCo2Node(), {
        label: "CO2 Leak",
        category: "Generated.Habitat",
        docPath: doc("leak-co2.md"),
        inputPorts: [...node.inputPorts],
        outputPorts: [...node.outputPorts],
        signature: {
            purpose: "CO2 mass flow leaking from a sealed volume through a passive leak, proportional to the leak rate and the CO2 concentration",
            inputs: {
                co2_concentration: { quantity: "Concentration", unit: "ppm", description: "CO2 concentration in the volume; 500 ppm when unwired" },
                lab_volume: { quantity: "Volume", unit: "m3", description: "volume of the sealed space; 30 m3 when unwired" },
            },
            outputs: {
                leak_flow: { quantity: "MassFlow", unit: "kg/s", description: "CO2 mass flow leaking out" },
            },
            capabilities: ["leak", "co2-source"],
        },
    });
}

import { cloneable, editable, viewable, inSlotOf, RuntimeNode } from "@spiky-panda/core";
import type { ICartesian, IChannel, IDeclaresPorts, IOlink, IPortDescriptor, ISession, Nullable } from "@spiky-panda/core";

/** A CO2 leak: mass flow out of a volume proportional to concentration and leak rate. */
export class LeakCo2Node extends RuntimeNode implements IDeclaresPorts {
    @cloneable private _leak_rate: number = 0.05; // L/min
    @cloneable private _leak_flow: number = 0;

    // The ports, on the instance: two signal inputs (optional with defaults), one signal output.
    public readonly inputPorts: ReadonlyArray<IPortDescriptor> = [
        { slot: "co2_concentration", optional: true, type: "float", kind: "signal" },
        { slot: "lab_volume", optional: true, type: "float", kind: "signal" },
    ];
    public readonly outputPorts: ReadonlyArray<IPortDescriptor> = [{ slot: "leak_flow", optional: false, type: "float", kind: "signal" }];

    public constructor(onsc: Nullable<IOlink[]> = null, opsc: Nullable<IOlink[]> = null, position?: ICartesian) {
        super(onsc, opsc, position);
    }

    /** An editable parameter: the leak rate in L/min. */
    @editable("number") public get leak_rate(): number {
        return this._leak_rate;
    }
    public set leak_rate(v: number) {
        this.setField("leak_rate", this._leak_rate, Number.isFinite(v) && v >= 0 ? v : this._leak_rate, (n) => (this._leak_rate = n));
    }

    /** A viewable: the computed leak flow on the last tick. */
    @viewable("number") public get lastLeakFlow(): number {
        return this._leak_flow;
    }

    public override reset(_session: ISession): void {
        this._leak_flow = 0;
    }

    /** One tick: read the inputs from the session's signals, compute the leak flow, publish on the output. */
    public override fire(session: ISession, _t: number): void {
        const links = session.graph.links as ReadonlyArray<IChannel>;
        let co2_concentration = 500; // ppm, default
        let lab_volume = 30; // m3, default

        // Read inputs from the session
        for (const link of this.opsc<IChannel>()) {
            if (!link.enabled) continue;
            const idx = links.indexOf(link);
            if (idx < 0) continue;
            const slot = String(inSlotOf(link));
            const v = session.readSignal(idx);
            if (typeof v === "number" && Number.isFinite(v)) {
                if (slot === "co2_concentration") co2_concentration = v;
                else if (slot === "lab_volume") lab_volume = v;
            }
        }

        // Compute leak flow: leak_rate (L/min) * co2_concentration (ppm) / 1e6 * lab_volume (m3) / 1000 / 60
        // This converts: L/min to m3/s (divide by 1000*60), ppm to mass fraction (divide by 1e6), m3 to L (multiply by 1000)
        // Result: kg/s
        const leak_flow = (this._leak_rate * co2_concentration / 1e6 * lab_volume) / 1000 / 60;

        this.setField("lastLeakFlow", this._leak_flow, leak_flow, (n) => (this._leak_flow = n));

        // Publish on the output
        for (const link of this.onsc<IChannel>()) {
            if (!link.enabled) continue;
            const idx = links.indexOf(link);
            if (idx >= 0 && String(link.slot) === "leak_flow") session.publish(idx, leak_flow);
        }
    }
}

export function createLeakCo2Node(): LeakCo2Node {
    return new LeakCo2Node();
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { LeakCo2Node } from "./leak-co2.node.js";

test("the leak rate is editable and its ports are declared", () => {
    const node = new LeakCo2Node();
    node.leak_rate = 0.1;
    assert.equal(node.leak_rate, 0.1);
    assert.deepEqual(
        node.inputPorts.map((p) => p.slot),
        ["co2_concentration", "lab_volume"]
    );
    assert.deepEqual(node.outputPorts.map((p) => p.slot), ["leak_flow"]);
});

test("leak flow computation matches the contract behavior", () => {
    const node = new LeakCo2Node();
    node.leak_rate = 0.05; // L/min

    // Test case 1: co2_concentration=500 ppm, lab_volume=30 m3
    // Expected: 0.05 * 500 / 1e6 * 30 / 1000 / 60 = 1.25e-8 kg/s
    let leak_flow = (node.leak_rate * 500 / 1e6 * 30) / 1000 / 60;
    assert.ok(Math.abs(leak_flow - 1.25e-8) < 1e-15, `leak_flow should be ~1.25e-8, got ${leak_flow}`);

    // Test case 2: co2_concentration=1000 ppm, lab_volume=50 m3
    // Expected: 0.05 * 1000 / 1e6 * 50 / 1000 / 60 = 4.166...e-8 kg/s
    leak_flow = (node.leak_rate * 1000 / 1e6 * 50) / 1000 / 60;
    assert.ok(Math.abs(leak_flow - 4.166666666666667e-8) < 1e-15, `leak_flow should be ~4.166e-8, got ${leak_flow}`);
});

